FROM shopwizard.tCatBrand

    AND SvcCode = #{pSvcCode}
    AND BrandId = #{pBrandId}

        AND (BrandKorName LIKE CONCAT('%',#{pBrandName},'%') OR BrandEngName LIKE CONCAT('%',#{pBrandName},'%'))


ORDER BY ${sidx} ${sord}
LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCatBrand

    AND SvcCode = #{pSvcCode}
    AND BrandId = #{pBrandId}

        AND (BrandKorName LIKE CONCAT('%',#{pBrandName},'%') OR BrandEngName LIKE CONCAT('%',#{pBrandName},'%'))

